<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';
$user = require_staff_or_admin();
$isAdmin = ($user['role'] ?? '') === 'admin';
$roleLabel = $isAdmin ? 'Administrator' : 'Staff member';
$initials = '';
foreach (preg_split('/\s+/', trim((string)$user['full_name'])) ?: [] as $part) { if ($part !== '') $initials .= strtoupper(substr($part, 0, 1)); if (strlen($initials) >= 2) break; }
$initials = $initials ?: 'U';

$q = trim((string)($_GET['q'] ?? ''));
$status = (string)($_GET['status'] ?? '');
$departmentId = filter_input(INPUT_GET, 'department_id', FILTER_VALIDATE_INT) ?: 0;
$sessionId = filter_input(INPUT_GET, 'session_id', FILTER_VALIDATE_INT) ?: 0;
$semesterId = filter_input(INPUT_GET, 'semester_id', FILTER_VALIDATE_INT) ?: 0;
$page = max(1, filter_input(INPUT_GET, 'page', FILTER_VALIDATE_INT) ?: 1);
$perPage = 15;
$allowedStatuses = ['pending', 'verified', 'rejected'];
if (!in_array($status, $allowedStatuses, true)) $status = '';

$where = [];
$params = [];
if (!$isAdmin) { $where[] = 'ss.uploaded_by = :viewer_id'; $params['viewer_id'] = (int)$user['id']; }
if ($q !== '') {
    $where[] = '(ss.original_filename LIKE :q1 OR ss.lecturer_name LIKE :q2 OR ss.reference_number LIKE :q3 OR c.course_code LIKE :q4 OR c.course_title LIKE :q5 OR u.full_name LIKE :q6)';
    $like = '%' . $q . '%';
    for ($i=1; $i<=6; $i++) $params['q'.$i] = $like;
}
if ($status !== '') { $where[] = 'ss.verification_status = :status'; $params['status'] = $status; }
if ($departmentId > 0) { $where[] = 'c.department_id = :department_id'; $params['department_id'] = $departmentId; }
if ($sessionId > 0) { $where[] = 'ss.academic_session_id = :session_id'; $params['session_id'] = $sessionId; }
if ($semesterId > 0) { $where[] = 'ss.semester_id = :semester_id'; $params['semester_id'] = $semesterId; }
$whereSql = $where ? ' WHERE ' . implode(' AND ', $where) : '';
$fromSql = ' FROM score_sheets ss JOIN courses c ON c.id=ss.course_id JOIN departments d ON d.id=c.department_id JOIN academic_sessions a ON a.id=ss.academic_session_id JOIN semesters sm ON sm.id=ss.semester_id JOIN users u ON u.id=ss.uploaded_by LEFT JOIN examination_types et ON et.id=ss.examination_type_id';
$count = $pdo->prepare('SELECT COUNT(*)' . $fromSql . $whereSql); $count->execute($params); $total = (int)$count->fetchColumn();
$totalPages = max(1, (int)ceil($total / $perPage)); if ($page > $totalPages) $page = $totalPages;
$sql = 'SELECT ss.id, ss.original_filename, ss.lecturer_name, ss.reference_number, ss.file_size, ss.mime_type, ss.file_hash, ss.verification_status, ss.created_at, c.course_code, c.course_title, d.department_name, a.session_name, sm.semester_name, et.examination_name, u.full_name AS uploader_name' . $fromSql . $whereSql . ' ORDER BY ss.created_at DESC, ss.id DESC LIMIT :limit OFFSET :offset';
$stmt = $pdo->prepare($sql); foreach ($params as $key=>$value) $stmt->bindValue(':'.$key, $value); $stmt->bindValue(':limit', $perPage, PDO::PARAM_INT); $stmt->bindValue(':offset', ($page-1)*$perPage, PDO::PARAM_INT); $stmt->execute(); $records = $stmt->fetchAll();
$departments = $pdo->query("SELECT id, department_name FROM departments WHERE status='active' ORDER BY department_name")->fetchAll();
$sessions = $pdo->query("SELECT id, session_name FROM academic_sessions ORDER BY session_name DESC")->fetchAll();
$semesters = $pdo->query('SELECT id, semester_name FROM semesters ORDER BY id')->fetchAll();
function archive_query(array $overrides = []): string { $values = array_merge($_GET, $overrides); foreach ($values as $k=>$v) if ($v === '' || $v === null || $v === 0) unset($values[$k]); return http_build_query($values); }
function archive_size(int $bytes): string { if ($bytes >= 1048576) return number_format($bytes/1048576, 2).' MB'; return number_format($bytes/1024, 1).' KB'; }
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Document Archive | ABCOAD ADSS</title><link rel="stylesheet" href="../assets/css/styles.css"><link rel="stylesheet" href="../assets/css/auth.css"><style>
.nav-link{text-decoration:none}.archive-wrap{max-width:1400px;margin:auto}.archive-head{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;margin-bottom:18px}.archive-head h2{margin:0 0 6px;color:#203b55;font-size:21px}.archive-head p{margin:0;color:#7b8b9a;font-size:11px;line-height:1.6}.archive-panel{background:#fff;border:1px solid #e6ebf0;border-radius:12px;padding:18px;box-shadow:0 5px 18px rgba(20,43,65,.035)}.filters{display:grid;grid-template-columns:2fr repeat(4,minmax(130px,1fr)) auto;gap:9px;align-items:end}.filters label{display:block;font-size:9px;font-weight:700;color:#52677a;margin:0 0 6px}.filters input,.filters select{width:100%;height:37px;border:1px solid #dfe6ed;border-radius:7px;padding:8px 9px;background:white;color:#34495e;font-size:10px}.filters button,.clear-link{height:37px;border:0;border-radius:7px;padding:0 13px;background:#203b55;color:#fff;font-size:10px;font-weight:700;cursor:pointer;text-decoration:none;display:inline-flex;align-items:center;justify-content:center}.clear-link{background:#edf2f6;color:#52677a;margin-left:5px}.archive-meta{display:flex;justify-content:space-between;gap:12px;margin:15px 0 10px;color:#7d8b98;font-size:10px}.table-scroll{overflow-x:auto}table.archive-table{width:100%;border-collapse:collapse;min-width:920px} .archive-table th{text-align:left;font-size:8px;letter-spacing:.5px;color:#91a0ad;padding:11px 9px;border-bottom:1px solid #e8edf1}.archive-table td{padding:12px 9px;border-bottom:1px solid #edf1f4;color:#53687a;font-size:10px;vertical-align:middle}.doc-name{font-weight:700;color:#344b60;max-width:220px;overflow-wrap:anywhere}.muted{display:block;color:#98a5b0;font-size:9px;margin-top:4px}.status-pill{display:inline-block;padding:5px 8px;border-radius:20px;font-size:8px;font-weight:700;text-transform:capitalize}.pending{background:#fff4dc;color:#9b6b0b}.verified{background:#e5f5ec;color:#168255}.rejected{background:#fde9e8;color:#c44c48}.actions{display:flex;gap:6px;white-space:nowrap}.action-link{display:inline-flex;padding:6px 8px;border-radius:6px;background:#edf4fa;color:#2c6f9f;text-decoration:none;font-weight:700;font-size:9px}.action-link.download{background:#f5f1e8;color:#876a25}.empty{text-align:center;padding:35px!important;color:#8b99a6!important}.pagination{display:flex;justify-content:flex-end;align-items:center;gap:6px;margin-top:16px}.pagination a,.pagination span{font-size:10px;padding:7px 10px;border-radius:6px;text-decoration:none;color:#52677a;background:#f0f3f6}.pagination .current{background:#203b55;color:white}.notice-line{font-size:9px;color:#8997a3;margin-top:12px;line-height:1.5}@media(max-width:1100px){.filters{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:700px){.archive-head{flex-direction:column}.filters{grid-template-columns:1fr 1fr}.filters .search-field{grid-column:1/-1}.filters .filter-actions{grid-column:1/-1}.archive-panel{padding:12px}}
</style></head><body><div class="app-shell"><aside class="sidebar" id="sidebar"><div class="brand"><img src="../assets/images/logo.png" alt="Audu Bako College of Agriculture logo" class="brand-logo"><div class="brand-name">AUDU BAKO COLLEGE<br>OF AGRICULTURE, DAMBATTA</div><div class="brand-tag">DIGITAL SCORE SHEET ARCHIVE</div></div><div class="nav-label">WORKSPACE</div><nav class="nav-menu"><a class="nav-link" href="<?= $isAdmin ? '../admin/index.php' : '../staff/index.php' ?>"><span class="nav-icon">▦</span>Dashboard</a><a class="nav-link" href="upload.php"><span class="nav-icon">⇧</span>Upload Score Sheet</a><a class="nav-link active" href="archive.php"><span class="nav-icon">▤</span>Document Archive</a><button class="nav-link" disabled><span class="nav-icon">✓</span>Verification Centre <span class="nav-coming">PHASE 7</span></button><?php if($isAdmin):?><a class="nav-link" href="../admin/users.php"><span class="nav-icon">♙</span>Staff Management</a><?php endif;?><button class="nav-link" disabled><span class="nav-icon">◷</span>Activity Logs <span class="nav-coming">PHASE 8</span></button></nav><div class="sidebar-bottom"><button class="nav-link" disabled><span class="nav-icon">⚙</span>Settings <span class="nav-coming">PHASE 8</span></button><div class="sidebar-user"><div class="avatar"><?= e($initials) ?></div><div><b><?= e($user['full_name']) ?></b><small><?= e($roleLabel) ?></small></div></div><form class="dashboard-user-form" method="post" action="../logout.php"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><button type="submit">↪ Sign out</button></form></div></aside><main class="main-area"><header class="topbar"><button class="mobile-menu" id="mobileMenu" type="button" aria-label="Open navigation" aria-controls="sidebar" aria-expanded="false">☰</button><div class="topbar-title"><span class="eyebrow">AUDU BAKO COLLEGE OF AGRICULTURE, DAMBATTA</span><h1>Document Archive</h1></div><div class="topbar-actions"><div class="top-profile"><div class="avatar"><?= e($initials) ?></div><div><b><?= e($user['full_name']) ?></b><small><?= e($roleLabel) ?></small></div></div></div></header><div class="content"><section class="archive-wrap"><div class="archive-head"><div><h2>Examination score sheet archive</h2><p><?= $isAdmin ? 'Search and retrieve all archived examination score sheets.' : 'Search and retrieve score sheets that you uploaded.' ?> Documents are served through access-controlled routes.</p></div><a class="btn btn-primary" href="upload.php">＋ Upload score sheet</a></div><section class="archive-panel"><form method="get" class="filters"><div class="search-field"><label for="q">SEARCH ARCHIVE</label><input id="q" name="q" value="<?= e($q) ?>" placeholder="Filename, lecturer, course, reference…"></div><div><label for="status">STATUS</label><select id="status" name="status"><option value="">All statuses</option><?php foreach($allowedStatuses as $s):?><option value="<?= e($s) ?>" <?= $status===$s?'selected':'' ?>><?= e(ucfirst($s)) ?></option><?php endforeach;?></select></div><?php if($isAdmin):?><div><label for="department_id">DEPARTMENT</label><select id="department_id" name="department_id"><option value="">All departments</option><?php foreach($departments as $d):?><option value="<?= (int)$d['id'] ?>" <?= $departmentId===(int)$d['id']?'selected':'' ?>><?= e($d['department_name']) ?></option><?php endforeach;?></select></div><?php endif;?><div><label for="session_id">ACADEMIC SESSION</label><select id="session_id" name="session_id"><option value="">All sessions</option><?php foreach($sessions as $s):?><option value="<?= (int)$s['id'] ?>" <?= $sessionId===(int)$s['id']?'selected':'' ?>><?= e($s['session_name']) ?></option><?php endforeach;?></select></div><div><label for="semester_id">SEMESTER</label><select id="semester_id" name="semester_id"><option value="">All semesters</option><?php foreach($semesters as $s):?><option value="<?= (int)$s['id'] ?>" <?= $semesterId===(int)$s['id']?'selected':'' ?>><?= e($s['semester_name']) ?></option><?php endforeach;?></select></div><div class="filter-actions"><button type="submit">Apply filters</button><a class="clear-link" href="archive.php">Clear</a></div></form><div class="archive-meta"><span>Showing <?= $total ? (($page-1)*$perPage+1) : 0 ?>–<?= min($page*$perPage,$total) ?> of <?= number_format($total) ?> document(s)</span><span>Newest uploads first</span></div><div class="table-scroll"><table class="archive-table"><thead><tr><th>DOCUMENT</th><th>COURSE / DEPARTMENT</th><th>SESSION / SEMESTER</th><th>LECTURER</th><?php if($isAdmin):?><th>UPLOADED BY</th><?php endif;?><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody><?php if(!$records):?><tr><td colspan="<?= $isAdmin?7:6 ?>" class="empty">No matching score sheets were found.</td></tr><?php else:foreach($records as $r):?><tr><td><div class="doc-name"><?= e($r['original_filename']) ?></div><span class="muted"><?= e(archive_size((int)$r['file_size'])) ?> · <?= e(strtoupper(pathinfo($r['original_filename'],PATHINFO_EXTENSION))) ?> · <?= e(date('d M Y',strtotime($r['created_at']))) ?></span></td><td><b><?= e($r['course_code']) ?></b><span class="muted"><?= e($r['course_title']) ?> · <?= e($r['department_name']) ?></span></td><td><?= e($r['session_name']) ?><span class="muted"><?= e($r['semester_name']) ?><?= $r['examination_name']?' · '.e($r['examination_name']):'' ?></span></td><td><?= e($r['lecturer_name']) ?></td><?php if($isAdmin):?><td><?= e($r['uploader_name']) ?></td><?php endif;?><td><span class="status-pill <?= e($r['verification_status']) ?>"><?= e($r['verification_status']) ?></span></td><td><div class="actions"><a class="action-link" href="file.php?id=<?= (int)$r['id'] ?>&mode=preview" target="_blank" rel="noopener">Preview</a><a class="action-link download" href="file.php?id=<?= (int)$r['id'] ?>&mode=download">Download</a></div></td></tr><?php endforeach;endif;?></tbody></table></div><?php if($totalPages>1):?><nav class="pagination" aria-label="Archive pages"><?php if($page>1):?><a href="?<?= e(archive_query(['page'=>$page-1])) ?>">← Previous</a><?php endif;?><span class="current">Page <?= $page ?> of <?= $totalPages ?></span><?php if($page<$totalPages):?><a href="?<?= e(archive_query(['page'=>$page+1])) ?>">Next →</a><?php endif;?></nav><?php endif;?><p class="notice-line">Access is limited by account permissions. Downloads are delivered by the application; the underlying storage directory is not linked directly.</p></section></section></div></main></div><script>(()=>{const b=document.getElementById('mobileMenu'),s=document.getElementById('sidebar');if(!b||!s)return;b.addEventListener('click',()=>{const o=s.classList.toggle('open');b.setAttribute('aria-expanded',o?'true':'false')});document.addEventListener('click',e=>{if(innerWidth<=760&&s.classList.contains('open')&&!s.contains(e.target)&&!b.contains(e.target)){s.classList.remove('open');b.setAttribute('aria-expanded','false')}})})();</script></body></html>
